import { creatureInfo } from './runtime/sources/common/src/ai/setup/creature_score';
import { draftGenomeCreatureScore } from './runtime/sources/common/src/ai/setup/draft_ship';
import { draftCreatureCoherenceAffinity } from './runtime/sources/common/src/ai/setup/draft_coherence';
import { draftSynergyEffects } from './runtime/sources/common/src/ai/setup/draft_battlefield_context';
import { rankedDraftStrengthCandidate } from './runtime/sources/common/src/simulation/ranked_draft_eval';
import { profiles } from './runtime/profiles';

const genome = rankedDraftStrengthCandidate(profiles.candidate.draftBase);
export const offensive = (id: number) => {
    const u = creatureInfo(id);
    return !!u && u.melee && !u.ranged && !u.rangedSpellDamage && !u.castsCraft && !u.castsAmplifiableBuff;
};
export const threat = (ids: readonly number[]) => {
    const units = [...new Set(ids)].flatMap(id => creatureInfo(id) ?? []);
    const shooters = units.filter(u => u.ranged), casters = units.filter(u => u.rangedSpellDamage);
    return { shooters: shooters.length, casters: casters.length,
        enabled: shooters.length + casters.length >= 2 || [...shooters,...casters].some(u => u.level >= 3) };
};
export function deliveryPool(current: number, available: readonly number[], context: any, variants: any, consumed: boolean) {
    const t = threat(context.knownOpponentCreatureIds), u = creatureInfo(current)!;
    if (consumed || context.ownCreatureIds.length < 3 || !t.enabled || !offensive(current) || u.canFly
        || ['Flesh Shield','Sanctuary','Range Null Field','No Fly'].some(a => u.abilities.includes(a))) return [];
    const own = context.ownCreatureIds as number[];
    if (own.filter(offensive).length < 1) return [];
    const noFly = context.knownOpponentCreatureIds.some((id: number) => creatureInfo(id)?.abilities.includes('No Fly'));
    const intrinsic = draftGenomeCreatureScore(genome,current);
    const coherence = draftCreatureCoherenceAffinity(current,{...context,synergyVariants:variants});
    const nativeSteps = draftSynergyEffects([...own,current],variants).movement;
    return available.filter(id => id !== current && offensive(id)
        && ((!noFly && creatureInfo(id)!.canFly) || draftSynergyEffects([...own,id],variants).movement > nativeSteps)
        && draftGenomeCreatureScore(genome,id) >= intrinsic - .05 * Math.max(1,Math.abs(intrinsic))
        && draftCreatureCoherenceAffinity(id,{...context,synergyVariants:variants}) >= coherence - .1);
}

