import assert from 'node:assert/strict';
import { runMatch } from './runtime/sources/common/src/simulation/battle_engine';
import { creatureInfo,creatureIdForName } from './runtime/sources/common/src/ai/setup/creature_score';
import { Grid } from './runtime/sources/common/src/grid/grid';
import { PathHelper } from './runtime/sources/common/src/grid/path_helper';
import { scatteredMountainsForSeed } from './runtime/sources/common/src/grid/scattered_mountains';
import { FightStateManager } from './runtime/sources/common/src/fights/fight_state_manager';
import { rushForwardFormation } from './runtime/sources/common/src/simulation/chaos_rush_research';
import { offensive,threat } from './policy';
import { prepareNative } from './runtime/native';
import { levels } from './runtime/plan';

const kinds=['Placement','Movement','Armor','Might','Sniper','Empower'];
const entries=(p:any)=>kinds.filter(k=>p[k]).map(kind=>({kind,value:p[kind]}));
/** Only known own setup and a fixed inert Peasant enter this projection; no actual enemy data. */
export function projectOwn(opening:any) {
    const team=opening.candidateTeam, own=team===2?'green':'red', enemy=team===2?'red':'green';
    const source=opening.config, data=opening.teams[team];
    const dummy={faction:'Life',creatureName:'Peasant',level:1,size:1,amount:1};
    const config:any={seed:source.seed,gridType:source.gridType,greenVersion:'v0.8',redVersion:'v0.8',
        sideOrientedPlacement:true,placementAugmentTiming:'setup-before-placement',synergyVariants:source.synergyVariants,
        roster:team===2?source.roster:[dummy],redRoster:team===1?source.redRoster:[dummy],maxLaps:0};
    for(const suffix of ['Doctrine','Augments','ArtifactT1','ArtifactT2','Synergies']) config[own+suffix]=structuredClone(source[own+suffix]);
    config[enemy+'Doctrine']=3;config[enemy+'Augments']=[];config[enemy+'Synergies']=[];config[enemy+'ArtifactT1']=0;config[enemy+'ArtifactT2']=0;
    const strategy=(physicalTeam:number)=>({version:'v0.8',decideTurn(){throw new Error('Projection may never take a turn')},
        placeArmy(units:any[]){return new Map(units.map((u,i)=>[u.getId(),physicalTeam===team?data.positions[i]:{x:physicalTeam===2?2:13,y:8}]))}});
    let context:any, projection:any;
    const stop=new Error('Own public fight-start projection complete');
    try {runMatch({...config,greenStrategyOverride:strategy(2),redStrategyOverride:strategy(1),
        beforeFightStart(c){context=c;},committedEventsObserver(o){
            if(!o.events.some(e=>e.type==='fight_started')) return;
            projection={settings:context.grid.getSettings(),fightProperties:context.fightProperties,units:context.unitsHolder.getAllAllies(team).map((u:any)=>({
                id:u.getId(),name:u.getName(),creatureId:creatureIdForName(u.getName()),amount:u.getAmountAlive(),
                x:u.getBaseCell().x,y:u.getBaseCell().y,width:u.getFootprintWidth(),height:u.getFootprintHeight(),
                steps:u.getSteps(),fly:u.canFly(),lava:u.canTraverseLava(),vine:u.hasAbilityActive('In Its Own World')
            }))};throw stop;
        }});
    }catch(e){if(e!==stop)throw e;}
    assert(projection,'Native start did not run');return projection;
}
export function funding(base:any[],ownIds:number[]) {
    const original=levels(base),result=[{id:'free-forward',levels:original,augments:base,cost:0}];
    const own=ownIds.map(id=>creatureInfo(id)!);
    for(const [placement,movement] of [[0,1],[0,2],[1,0],[1,1]]) {
        if(original.Placement>placement||original.Movement>movement)continue;
        const p={...original,Placement:placement,Movement:movement};
        let cost=placement-original.Placement+movement-original.Movement,remaining=cost;
        if(!cost)continue;
        for(const kind of ['Sniper','Empower','Might'] as const) {
            const floor=kind==='Sniper'?(own.some(u=>u.ranged)?1:0):kind==='Empower'?(own.some(u=>u.dealsMagicDamage)?original.Empower:0):original.Might;
            const n=Math.min(remaining,Math.max(0,p[kind]-floor));p[kind]-=n;remaining-=n;
        }
        if(remaining)continue;
        assert.equal(p.Armor,original.Armor);assert.equal(Object.values(p).reduce((a,b)=>a+b,0),Object.values(original).reduce((a,b)=>a+b,0));
        result.push({id:`p${placement}-m${movement}`,levels:p,augments:entries(p) as any,cost});
    }
    return result.sort((a,b)=>a.cost-b.cost||a.levels.Placement-b.levels.Placement||a.levels.Movement-b.levels.Movement);
}
/** Compare fixed hypothetical backline cells, never the concealed deployment. */
export function reachScore(projection:any,opening:any) {
    FightStateManager.getInstance().setFightProperties(projection.fightProperties);
    const grid=new Grid(projection.settings,opening.config.gridType);
    if(opening.config.gridType===4)grid.setScatteredMountains(scatteredMountainsForSeed(`sim-${opening.config.seed}`).map(r=>r.cell));
    for(const barrel of opening.teams[opening.candidateTeam].barrels)assert(grid.placeArtifactBarrel(barrel.team,barrel.index,barrel.cell));
    const matrix=grid.getMatrixNoUnits(),path=new PathHelper(projection.settings),team=opening.candidateTeam;
    const totals=new Map<string,number>();for(const u of projection.units)totals.set(u.name,(totals.get(u.name)??0)+u.amount);
    let score=0;const rows:any[]=[];
    for(const u of projection.units) {
        if(!offensive(u.creatureId)||(u.amount<2&&totals.get(u.name)!>1)||u.amount<totals.get(u.name)!/2)continue;
        const routes=path.getMovePath({x:u.x,y:u.y},matrix,u.steps,undefined,u.fly,u.width===1&&u.height===1,u.lava,u.vine,u.width,u.height).knownPaths;
        const cells=[{x:u.x,y:u.y},...[...routes.values()].flatMap((paths:any)=>paths.map((p:any)=>p.cell))];
        let contact=0;
        for(const x of team===2?[12,13,14]:[1,2,3])for(const y of [3,6,9,12])
            if(cells.some(c=>Math.max(0,c.x-u.width+1-x,x-c.x)<=1&&Math.max(0,c.y-u.height+1-y,y-c.y)<=1))contact++;
        const weight=u.amount*creatureInfo(u.creatureId)!.exp/1000;
        score+=weight*contact/12;rows.push({name:u.name,steps:u.steps,fly:u.fly,contact,weight});
    }
    return {score,rows};
}
export function forwardGeometry(session:any,team:number,units:any[],positions:any[]) {
    const totals=new Map<string,number>();for(const u of units)totals.set(u.getName(),(totals.get(u.getName())??0)+u.getAmountAlive());
    const bodies=units.map((u,i)=>({id:u.getId(),x:positions[i].x,y:positions[i].y,width:u.getFootprintWidth(),height:u.getFootprintHeight(),
        eligible:offensive(creatureIdForName(u.getName())!)&&(u.getAmountAlive()>1||totals.get(u.getName())===1)&&u.getAmountAlive()>=totals.get(u.getName())!/2}));
    const allowed=session.getPlacementsForTeam(team)[0].possibleCellPositions();
    const neutral=session.grid.getGridType()===4?scatteredMountainsForSeed(session.gameId).map(r=>r.cell):[];
    const moved=rushForwardFormation(bodies,allowed,neutral,team===2?1:-1);
    return {bodies:units.map(u=>[u.getName(),u.getAmountAlive(),u.getFootprintWidth(),u.getFootprintHeight()]),positions:moved.map(u=>({x:u.x,y:u.y}))};
}
export function chooseDelivery(config:any,seed:number,team:number) {
    const native={...prepareNative(config,seed,team),candidateTeam:team};
    const receipt=native.setupReceipts.find(r=>r.team===team),own=native.publicPlans[team].input.ownCreatureIds;
    if(!threat(receipt.context.publicOpponentCreatureIds).enabled||own.filter(offensive).length<2||levels(receipt.augments).Placement||levels(receipt.augments).Movement)return {native,selected:native,free:native,choices:[],selectedId:'native'};
    const baseline=reachScore(projectOwn(native),native),choices:any[]=[];
    let selected=native,selectedId='native',best=baseline.score,selectedPlan:any;
    for(const plan of funding(receipt.augments,own)) {
        const opening={...prepareNative(config,seed,team,{ownAugments:plan.augments,matchedGeometry:forwardGeometry}),candidateTeam:team};
        const projected=projectOwn(opening),probe=reachScore(projected,opening);
        choices.push({id:plan.id,augments:plan.augments,probe,projected:projected.units});
        if(probe.score>best+1e-9&&(plan.cost===0||probe.score>=best+.25)){best=probe.score;selected=opening;selectedId=plan.id;selectedPlan=plan;}
    }
    let free=selected;
    if(selectedPlan&&selectedPlan.levels.Placement>0){
        const match=funding(receipt.augments,own).find(p=>p.levels.Placement===0&&p.levels.Movement===selectedPlan.levels.Movement);
        assert(match,'Paid plan must have a fully funded free counterpart');
        free={...prepareNative(config,seed,team,{ownAugments:match.augments,matchedGeometry:forwardGeometry}),candidateTeam:team};
    }
    return {native,selected,free,choices,selectedId,baseline};
}

