import assert from 'node:assert/strict';
import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {gunzipSync,gzipSync} from 'node:zlib';
import {createHash} from 'node:crypto';
import {play} from './runtime/play';
import {digest} from './runtime/io';
const P=import.meta.dir;
const read=(f:string)=>JSON.parse(readFileSync(`${P}/${f}`,'utf8'));
const zipped=(f:string)=>JSON.parse(gunzipSync(readFileSync(`${P}/${f}`)).toString());
const sha=(b:any)=>createHash('sha256').update(b).digest('hex');
const registration=read('registration.json');
for(const [file,hash]of Object.entries(registration.sources))assert.equal(sha(readFileSync(`${P}/${file}`)),hash,file);
const [host='m4',wt='0',nt='1',stage='screen']=process.argv.slice(2),worker=Number(wt),workers=Number(nt);
let jobs=read('census.json').receipts;
if(stage==='cold')jobs=jobs.filter((_:any,i:number)=>[0,18,36].includes(i));
mkdirSync(`${P}/${stage}`,{recursive:true});
for(let i=worker;i<jobs.length;i+=workers){
    const job=jobs[i],data=zipped(`openings/${job.id}.json.gz`),cache:any={};
    const modes=['native','draft','setup','combined','free'];
    if((i+job.seat)%2)modes.reverse();
    for(const mode of modes){
        assert(Date.now()<registration.cutoffUnix*1000,'Fixed cutoff exceeded');
        const key=data.keys[mode],known=stage==='screen'?cache[key]:undefined;
        const result=known?{...known,elapsedMs:0}:play(data.opened[mode],data.task.evalFutures[0]);
        const row={...result,openingSha256:digest(data.opened[mode]),id:job.id,task:data.task,seat:job.seat,mode,host,battleInputKey:key,
            reusedFrom:known?.mode??null,registrationSha256:sha(readFileSync(`${P}/registration.json`))};
        writeFileSync(`${P}/${stage}/${job.id}-${mode}.json.gz`,gzipSync(JSON.stringify(row)));
        assert(row.qualityPassed,row.error);
        cache[key]={...result,mode};
        if(stage==='cold'){
            const before=zipped(`screen/${job.id}-${mode}.json.gz`);
            for(const field of ['result','turns','events','health'])assert.equal(digest(row[field]),digest(before[field]),`${job.id}/${mode}/${field}`);
        }
    }
    console.log(JSON.stringify({id:job.id,host,stage,completed:true}));
}

