import { readFileSync, writeFileSync } from 'node:fs';
import { draft } from './runtime/opening';
import { creatureInfo } from './runtime/sources/common/src/ai/setup/creature_score';
import { assertPackageIdentity } from './runtime/identity';
assertPackageIdentity();
const tasks=JSON.parse(readFileSync(new URL('manifest.json',import.meta.url),'utf8')).pool;
const rows:any[]=[];
for(const task of tasks) {
    const d=draft(task), eligible=d.interventions.filter((r:any)=>r.pool.length);
    rows.push({task,eligible,decisions:d.interventions.map((r:any)=>({
        own:r.context.ownCreatureIds,known:r.context.knownOpponentCreatureIds,
        knownNames:r.context.knownOpponentCreatureIds.map((id:number)=>creatureInfo(id)!.name),
        native:r.native,nativeName:creatureInfo(r.native)!.name,pool:r.pool,
        choices:r.available,threat:r.threat,variants:r.variants,
    }))});
}
const counts:any={families:rows.length,eligibleFamilies:rows.filter(r=>r.eligible.length).length,byDoctrine:{},byMap:{}};
for(const d of [1,2,3]) counts.byDoctrine[d]={families:rows.filter(r=>r.task.d1===d).length,eligible:rows.filter(r=>r.task.d1===d&&r.eligible.length).length};
for(const m of [1,3,4]) counts.byMap[m]={families:rows.filter(r=>r.task.map===m).length,eligible:rows.filter(r=>r.task.map===m&&r.eligible.length).length};
