import assert from 'node:assert/strict';
import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {gzipSync} from 'node:zlib';
import {draft,seatedDraft} from './runtime/opening';
import {chooseDelivery,projectOwn} from './reach';
import {prepareNative} from './runtime/native';
import {digest} from './runtime/io';
import {battleInputKey} from './runtime/battle-key';
import {deliveryPool} from './policy';

const audit=JSON.parse(readFileSync(new URL('draft-audit.json',import.meta.url),'utf8'));
const selected:any[]=[];
for(const map of [1,3,4])for(const d1 of [1,2,3]) {
    const rows=audit.rows.filter((r:any)=>r.task.map===map&&r.task.d1===d1&&r.eligible.length).slice(0,3);
    assert.equal(rows.length,3,`Incomplete eligibility stratum ${map}/${d1}`);
    selected.push(...rows.map((r:any)=>r.task));
}
writeFileSync(new URL('selected-cases.json',import.meta.url),JSON.stringify(selected,null,2)+'\n');
mkdirSync(new URL('openings/',import.meta.url),{recursive:true});
const receipts:any[]=[];
for(const task of selected) {
    const native=draft(task),mobile=draft(task,'mobile');
    assert.equal(mobile.interventions.filter((r:any)=>r.selected!==r.native).length,1,'One durable override per draft including retries');
    for(const r of native.interventions)assert.deepEqual(deliveryPool(r.native,r.available,{...r.context,knownOpponentCreatureIds:[]},r.variants,false),[]);
    for(const seat of [0,1]) {
        const a=seatedDraft(native,!!seat),b=seatedDraft(mobile,!!seat),seed=seat?task.reverseSetup:task.setup;
        const n=chooseDelivery(a.config,seed,a.candidateTeam),m=chooseDelivery(b.config,seed,b.candidateTeam);
        const opened:any={native:n.native,draft:m.native,setup:n.selected,combined:m.selected,free:m.free};
        for(const key of ['setup'])assert.deepEqual(opened[key].teams[3-a.candidateTeam],opened.native.teams[3-a.candidateTeam]);
        for(const key of ['combined','free'])assert.deepEqual(opened[key].teams[3-b.candidateTeam],opened.draft.teams[3-b.candidateTeam]);
        const id=`${task.id}-s${seat}`;
        const keys=Object.fromEntries(Object.entries(opened).map(([mode,o])=>[mode,battleInputKey(o,task.evalFutures[0])]));
        writeFileSync(new URL(`openings/${id}.json.gz`,import.meta.url),gzipSync(JSON.stringify({task,seat,id,native,mobile,nativePlan:n,mobilePlan:m,opened,keys})));
        receipts.push({id,task,seat,keys,nativePlan:n.selectedId,mobilePlan:m.selectedId,
            initialVisibility:native.interventions.find((r:any)=>r.pool.length).context.knownOpponentCreatureIds.length,
            proposal:mobile.interventions.find((r:any)=>r.selected!==r.native),
            combinedChanges:keys.combined!==keys.native,setupChanges:keys.combined!==keys.draft,
            paidPlacement:m.selected.config[b.candidateTeam===2?'greenAugments':'redAugments'].some((x:any)=>x.kind==='Placement'&&x.value>0)});
        console.log(JSON.stringify({id,nativePlan:n.selectedId,mobilePlan:m.selectedId}));
    }
}
const summary={qualityPassed:true,families:selected.length,seats:receipts.length,logicalBattles:receipts.length*5,
    distinctBattles:receipts.reduce((s,r)=>s+new Set(Object.values(r.keys)).size,0),
    setupChangedSeats:receipts.filter(r=>r.setupChanges).length,paidPlacementSeats:receipts.filter(r=>r.paidPlacement).length,
    proposals:receipts.filter(r=>r.seat===0).map(r=>({doctrine:r.task.d1,map:r.task.map,known:r.initialVisibility,from:r.proposal.native,to:r.proposal.selected})),receipts};
writeFileSync(new URL('census.json',import.meta.url),JSON.stringify(summary,null,2)+'\n');
console.log(JSON.stringify({...summary,receipts:undefined,proposals:undefined}));

