import assert from 'node:assert/strict';
import {readFileSync,writeFileSync} from 'node:fs';
import {gunzipSync} from 'node:zlib';
import {projectOwn,reachScore} from './reach';
import {digest} from './runtime/io';
import {creatureInfo} from './runtime/sources/common/src/ai/setup/creature_score';
const census=JSON.parse(readFileSync(new URL('census.json',import.meta.url),'utf8'));
let probes=0,heavySingle=false;
for(const i of [0,18,36]) {
    const data=JSON.parse(gunzipSync(readFileSync(new URL(`openings/${census.receipts[i].id}.json.gz`,import.meta.url))).toString());
    for(const mode of ['native','combined']) {
        const opening=data.opened[mode],other=3-opening.candidateTeam,prefix=other===2?'green':'red';
        const before=projectOwn(opening),score=reachScore(before,opening);
        const changed=structuredClone(opening);
        changed.config[other===2?'roster':'redRoster']=[];
        for(const suffix of ['ArtifactT1','ArtifactT2','Augments','Synergies','Doctrine'])changed.config[prefix+suffix]={concealedDecoy:true};
        changed.teams[other]={hidden:true};changed.futureCombatSeed='forbidden';
        const after=projectOwn(changed),afterScore=reachScore(after,changed);
        assert.equal(digest(before.units),digest(after.units));assert.deepEqual(score,afterScore);
        assert(before.units.every((u:any)=>Number.isFinite(u.steps)&&u.steps>0));
        probes++;
    }
}
for(const row of census.receipts){
    const data=JSON.parse(gunzipSync(readFileSync(new URL(`openings/${row.id}.json.gz`,import.meta.url))).toString());
    for(const plan of data.mobilePlan.choices)for(const unit of plan.projected)
        if(unit.amount===1&&unit.name==='Black Dragon'){
            assert(plan.probe.rows.some((r:any)=>r.name===unit.name),'A whole one-creature carry is not a utility split');heavySingle=true;
        }
}
assert(heavySingle);
writeFileSync(new URL('input-checks.json',import.meta.url),JSON.stringify({qualityPassed:true,hiddenStateNoninterferenceProbes:probes,wholeSingleCreatureCarryIncluded:heavySingle},null,2)+'\n');
console.log('Public-only projection and whole-single-creature carry checks passed');

