from pathlib import Path
import datetime,gzip,hashlib,json
P=Path(__file__).resolve().parent;client=P.parents[3]
namespace=P.name+'-fresh-v1'
def perm(n):
 n&=0xffffffff;n^=n>>16;n=n*0x85ebca6b&0xffffffff;n^=n>>13;n=n*0xc2b2ae35&0xffffffff;return(n^(n>>16))&0xffffffff
def expansion(n):return[(n+i)&0xffffffff for i in range(32)]+[perm(n+i)for i in range(32)]
preimages=[int.from_bytes(hashlib.sha256(f'{namespace}:{i}'.encode()).digest()[:4],'little')for i in range(1,20481)]
queries={v for n in preimages for v in expansion(n)};blocked=set();ledgers={}
def collect(o):
 if isinstance(o,bool):return
 if isinstance(o,int):
  if o in queries:blocked.add(o)
 elif isinstance(o,list):
  for v in o:collect(v)
 elif isinstance(o,dict):
  for k,v in o.items():
   if k=='reservedScannedPreimages':
    for n in v:
     for x in expansion(n):
      if x in queries:blocked.add(x)
   collect(v)
paths=[P.parent/'peasant-exchange-angles-20261116/exclusions.json.gz']
paths+=sorted((client/'game/heroes-of-crypto-common/docs/evidence').rglob('*.json'))
paths+=sorted(P.parent.glob('*/reserved*.json'))
paths+=sorted(P.parent.glob('*/prelaunch-peer-amendment/**/reserved*.json'))
paths+=sorted((client/'game/heroes-of-crypto-common/src/simulation/v0_9/checkpoints').rglob('*registration*.json'))
for path in dict.fromkeys(paths):
 if path.parent==P:continue
 raw=path.read_bytes();collect(json.loads(gzip.decompress(raw)if path.name.endswith('.gz')else raw));ledgers[str(path.relative_to(client))]=hashlib.sha256(raw).hexdigest()
for name in ['ranked-geometry-aligned12h-20261116','ranked-geometry-real-outcomes-20261116']:
 directory=P.parent/name;meta=json.loads((directory/('fresh-seed-admission.json'if'aligned12h'in name else'seed-admission.json')).read_text())
 count=sum(meta['fixedFamilies'].values())*11+meta['allocationRejections']if'aligned12h'in name else meta['scannedCounters'];ns=name+'-fresh-v1'if'aligned12h'in name else meta['namespace']
 for i in range(1,count+1):
  n=int.from_bytes(hashlib.sha256(f'{ns}:{i}'.encode()).digest()[:4],'little')
  for x in expansion(n):
   if x in queries:blocked.add(x)
 ledgers['derived:'+ns]=str(count)
seen=set();accepted=[];scans=[]
for counter,n in enumerate(preimages,1):
