import { digest } from "./io";
// Exactly the complete opening fields consumed by frozen fightNative plus scoring seat.
// Package/source/runtime/profile hashes are sealed separately for the entire campaign.
export function battleInputKey(opening: any, combatSeed: number) {
    return digest({
        config: opening.config,
        teams: opening.teams,
        terrain: opening.terrain,
        candidateTeam: opening.candidateTeam,
        combatSeed,
    });
}

