import assert from "node:assert/strict";
import { fightNative } from "./native";
import { digest } from "./io";
import { validatePremiumHealthLedger } from "./sources/common/src/simulation/ai_meta_health_ledger";
export function play(opening: any, combatSeed: number) {
    const turns: any[] = [],
        events: any[] = [],
        health: any[] = [];
    let result: any,
        receipt: any,
        error: any = null;
    const start = performance.now();
    try {
        ({ result, receipt } = fightNative(opening, combatSeed, {
            turnExecutionObserver: (x: any) => turns.push(x),
            committedEventsObserver: (x: any) => events.push(x),
            committedHealthObserver: (x: any) => health.push(x),
        }));
        validatePremiumHealthLedger(health, events);
        assert(receipt.qualityPassed, "Both-team A19/zero-rejection quality gate");
    } catch (e) {
        error = String(e) + "\n" + (e as any)?.stack;
    }
    const score = result
        ? result.winner === "draw"
            ? 0.5
            : Number(result.winner === (opening.candidateTeam === 2 ? "green" : "red"))
        : null;
    return {
        qualityPassed: !error,
        error,
        openingSha256: digest(opening),
        combatSeed,
        candidateTeam: opening.candidateTeam,
        result,
        receipt,
        turns,
        events,
        health,
        healthHash: digest(health),
        score,
        elapsedMs: performance.now() - start,
    };
}

